#include <stdbool.h>
#include <stddef.h>
bool average(const int values[], size_t count, double *result) {
 if (values == NULL || result == NULL || count == 0) return false;
 long long sum = 0;
 for (size_t i=0; i<count; ++i) sum += values[i];
 *result = (double)sum / (double)count;
 return true;
}
